sql_query:
SELECT "Trial phase"
FROM clinical_trials
WHERE "Cancer type" = 'Colorectal' AND "Included in MA" = 'No' AND "Name of ICI" = 'Atezolizumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Trial phase" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Colorectal' AND "Included in MA" = 'No' AND "Name of ICI" = 'Atezolizumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_phase_bucket(source_value) AS "phase_bucket"
FROM base;
